const AUTORIZADOS = ['REDACTED@example.invalid'];
const m = $input.first().json;
const assunto = String(m.subject || '');
const de = String(((m.from || {}).emailAddress || {}).address || '').toLowerCase();
const cod = ((assunto.match(/PRP-\d{4}-\d{4}/i) || [])[0] || '').toUpperCase();
const html = String((m.body && m.body.content) || m.bodyPreview || '');
const texto = html.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<br\s*\/?>|<\/p>|<\/div>|<\/tr>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const linhas = texto.split('\n').map(l => l.replace(/\s+/g, ' ').trim()).filter(Boolean);
let primeira = linhas[0] || '';
if (/^(de|from|enviado|sent|on .* wrote|em .* escreveu)\s*:/i.test(primeira)) primeira = '';
const base = { codigo: cod, remetente: de, assunto, comentario: primeira.slice(0, 300) };
if (!cod) return [{ json: { ...base, acao: 'ignorar', motivo: 'sem código PRP' } }];
if (!/^\s*(re|res|rv)\s*:/i.test(assunto)) return [{ json: { ...base, acao: 'ignorar', motivo: 'não é uma resposta' } }];
if (!AUTORIZADOS.includes(de)) return [{ json: { ...base, acao: 'ignorar', motivo: 'remetente não autorizado' } }];
const aprova = /^(ok|aprovo|aprovado|aprovada)\s*[.!]?$/i.test(primeira);
return [{ json: { ...base, acao: aprova ? 'aprovar' : 'comentario', motivo: aprova ? 'resposta OK' : 'resposta com comentário' } }];

const r = $('Interpretar resposta').first().json;
const p = $input.first().json || {};
const cod = r.codigo;
if (!p.id) return [{ json: { ...r, aplicar: false, slack_texto: '⚠️ Recebi uma resposta a ' + cod + ' mas a proposta não existe.' } }];
if (r.acao === 'comentario') return [{ json: { ...r, aplicar: false, slack_texto: '💬 A Bárbara respondeu a *' + cod + '* com um comentário (a proposta continua em validação): "' + r.comentario + '"' } }];
if (p.estado !== 'em_validacao') return [{ json: { ...r, aplicar: false, slack_texto: '⚠️ Aprovação ignorada: *' + cod + '* está no estado ' + p.estado + ' (e não em validação).' } }];
return [{ json: { ...r, aplicar: true, aprovada_por: r.remetente, aprovada_em: new Date().toISOString(), slack_texto: '✅ Proposta *' + cod + '* aprovada por ' + r.remetente + '. O envio ao cliente ainda é manual.' } }];
